css='''\n/* CJ24H-PWA-PUSH-V1 */\n.cj-continuity{display:none;gap:12px;align-items:center;margin:0 0 10px;padding:12px 13px;border:1px solid rgba(94,224,160,.16);border-radius:14px;background:linear-gradient(180deg,rgba(255,255,255,.035),rgba(255,255,255,.018));box-shadow:0 10px 30px rgba(0,0,0,.18)}\n.cj-continuity.show{display:flex}.cj-continuity img{width:42px;height:42px;border-radius:11px;box-shadow:0 4px 14px rgba(0,0,0,.24);flex:0 0 auto}.cj-continuity__copy{min-width:0;flex:1}.cj-continuity__title{font-size:.82rem;font-weight:600;color:rgba(255,255,255,.94);margin-bottom:2px}.cj-continuity__sub{font-size:.68rem;line-height:1.45;color:rgba(255,255,255,.42)}.cj-continuity__actions{display:flex;gap:6px;flex-wrap:wrap;margin-top:7px}.cj-mini-btn{border:1px solid rgba(94,224,160,.22);background:rgba(94,224,160,.07);color:#8be8b4;border-radius:9px;padding:7px 9px;font:600 .67rem 'Outfit',sans-serif;cursor:pointer}.cj-mini-btn.secondary{border-color:rgba(255,255,255,.09);background:rgba(255,255,255,.035);color:rgba(255,255,255,.66)}\n.chat-consulta{background:rgba(255,255,255,.018)!important;border-color:rgba(255,255,255,.07)!important;box-shadow:0 18px 55px rgba(0,0,0,.22)!important}.chat-header-box{background:rgba(255,255,255,.018)!important;border-bottom-color:rgba(255,255,255,.055)!important}.medico-entrou-banner{background:rgba(94,224,160,.055)!important;border-color:rgba(94,224,160,.14)!important}.chat-input-row{background:rgba(5,12,10,.88)!important;border-top-color:rgba(255,255,255,.055)!important}.cj-avatar-mark,.cj-doctor-mark{font-family:'Outfit',sans-serif!important;font-weight:700!important;letter-spacing:.02em!important;color:#8be8b4!important}.cj-wait-dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:#8be8b4;margin-right:6px;box-shadow:0 0 0 4px rgba(94,224,160,.08)}\n.cj-install-sheet{position:fixed;inset:0;z-index:9999;background:rgba(0,0,0,.68);backdrop-filter:blur(10px);display:flex;align-items:flex-end;justify-content:center;padding:14px}.cj-install-sheet__card{width:100%;max-width:430px;background:#0b1512;border:1px solid rgba(255,255,255,.09);border-radius:22px;padding:18px;box-shadow:0 24px 80px rgba(0,0,0,.5)}.cj-install-sheet__title{font-size:1rem;font-weight:650;margin-bottom:6px}.cj-install-sheet__text{font-size:.78rem;line-height:1.55;color:rgba(255,255,255,.55)}.cj-install-sheet__close{width:100%;margin-top:14px;border:0;border-radius:11px;padding:11px;background:rgba(255,255,255,.06);color:#fff;font:600 .78rem 'Outfit',sans-serif}\n@media(max-width:520px){.cj-continuity{align-items:flex-start}.cj-continuity img{width:38px;height:38px}.cj-continuity__actions{width:100%}}\n'''
s=s.replace('</style>',css+'\n</style>',1)
