js=r'''\n// CJ24H-PWA-PUSH-V1\nvar cjInstallPrompt=null,cjPushBusy=false;\nfunction cjB64ToU8(v){var p='='.repeat((4-v.length%4)%4),b=(v+p).replace(/-/g,'+').replace(/_/g,'/'),r=atob(b),o=new Uint8Array(r.length);for(var i=0;i<r.length;i++)o[i]=r.charCodeAt(i);return o;}\nfunction cjStandalone(){return window.matchMedia&&window.matchMedia('(display-mode: standalone)').matches||window.navigator.standalone===true;}\nfunction cjIsIOS(){return /iphone|ipad|ipod/i.test(navigator.userAgent||'');}\nfunction cjAtualizarContinuity(){var box=document.getElementById('cjContinuity');if(!box||!atendimentoId)return;box.classList.add('show');var ib=document.getElementById('cjInstallBtn');if(ib&&cjStandalone())ib.style.display='none';var pb=document.getElementById('cjPushBtn');if(pb&&window.Notification&&Notification.permission==='granted'){pb.textContent='Notificações ativadas';pb.disabled=true;cjRegistrarPushPaciente(false);}}\nwindow.addEventListener('beforeinstallprompt',function(e){e.preventDefault();cjInstallPrompt=e;cjAtualizarContinuity();});\nwindow.addEventListener('appinstalled',function(){cjInstallPrompt=null;cjAtualizarContinuity();});\nfunction cjMostrarInstrucaoIOS(){var x=document.createElement('div');x.className='cj-install-sheet';x.innerHTML='<div class="cj-install-sheet__card"><div class="cj-install-sheet__title">Adicionar ConsultaJá24h à Tela de Início</div><div class="cj-install-sheet__text">No Safari, toque em <strong>Compartilhar</strong> e depois em <strong>Adicionar à Tela de Início</strong>. O ícone da ConsultaJá24h ficará no seu celular e este atendimento continuará acessível pelo mesmo aparelho.</div><button class="cj-install-sheet__close">Entendi</button></div>';x.querySelector('button').onclick=function(){x.remove()};x.onclick=function(e){if(e.target===x)x.remove()};document.body.appendChild(x);}\nasync function cjInstalarApp(){if(cjStandalone())return;if(cjInstallPrompt){var p=cjInstallPrompt;cjInstallPrompt=null;await p.prompt();try{await p.userChoice}catch(e){}cjAtualizarContinuity();return;}if(cjIsIOS())return cjMostrarInstrucaoIOS();var x=document.createElement('div');x.className='cj-install-sheet';x.innerHTML='<div class="cj-install-sheet__card"><div class="cj-install-sheet__title">Adicionar ao celular</div><div class="cj-install-sheet__text">Abra o menu do navegador e escolha <strong>Instalar app</strong> ou <strong>Adicionar à tela inicial</strong>. No Android compatível, o botão de instalação também pode aparecer automaticamente.</div><button class="cj-install-sheet__close">Entendi</button></div>';x.querySelector('button').onclick=function(){x.remove()};document.body.appendChild(x);}\nwindow.cjInstalarApp=cjInstalarApp;\nasync function cjRegistrarPushPaciente(pedir){if(cjPushBusy||!atendimentoId||!pacienteTel||!('serviceWorker'in navigator)||!('PushManager'in window)||!('Notification'in window))return false;cjPushBusy=true;var b=document.getElementById('cjPushBtn');try{var perm=Notification.permission;if(perm==='default'&&pedir)perm=await Notification.requestPermission();if(perm!=='granted')return false;if(b){b.textContent='Ativando...';b.disabled=true}var reg=await navigator.serviceWorker.register('/atendimento/push-sw.js',{scope:'/atendimento/'});var kd=await (await fetch(API+'/api/web-push/public-key')).json();if(!kd.ok||!kd.publicKey)throw new Error('push_indisponivel');var sub=await reg.pushManager.getSubscription();if(!sub)sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:cjB64ToU8(kd.publicKey)});var r=await fetch(API+'/api/web-push/chat-subscribe',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({papel:'paciente',atendimentoId:atendimentoId,telefone:pacienteTel,subscription:sub.toJSON()})});var d=await r.json().catch(function(){return{}});if(!r.ok||!d.ok)throw new Error(d.error||'push_failed');if(b){b.textContent='Notificações ativadas';b.disabled=true}return true;}catch(e){if(b){b.textContent='Ativar notificações';b.disabled=false}return false;}finally{cjPushBusy=false;}}\nfunction cjAtivarPushPaciente(){cjRegistrarPushPaciente(true)}window.cjAtivarPushPaciente=cjAtivarPushPaciente;\n(function(){var tries=0,t=setInterval(function(){tries++;cjAtualizarContinuity();if(window.Notification&&Notification.permission==='granted')cjRegistrarPushPaciente(false);if((atendimentoId&&tries>3)||tries>20)clearInterval(t)},700)})();\n'''
pos=s.rfind('</script>')
if pos<0: raise SystemExit('script end not found')
s=s[:pos]+js+s[pos:]
p.write_text(s)
print('patched atendimento/index.html')
